detaileddescription.para:
使用示例： //解析请求
autorequest=http_server_request::parse(
"GET/api/users?id=123HTTP/1.1\r\n"
"Host:example.com\r\n"
"Cookie:session=abc123\r\n"
"\r\n"
);

//获取请求信息
if(request.method==http_method::GET()){
stringid=request.parameter("id");
}

//获取Cookie
stringsession_id=request.cookie("session");

//获取客户端IP（支持代理）
stringclient_ip=request.client_ip();

//检查是否为AJAX请求
if(request.is_ajax()){
//返回JSON响应
}

//获取会话
if(request.has_session()){
auto*session=request.session;
session->touch();
}
